try {
 for (const width of [458, 884, 1920]) {
  const page = await browser.newPage({viewport:{width,height:900},serviceWorkers:'block'});
  const errors=[];
  page.on('pageerror',e=>errors.push(e.message));
  await page.route('**/*',async route=>{
   const url=new URL(route.request().url());
   if(url.pathname==='/') return route.fulfill({contentType:'text/html',body:`<html><head><meta name="viewport" content="width=device-width,initial-scale=1"></head><body style="background:#191c20"><script type="module">import {initHUD} from '/src/display/ui/hud.js';initHUD();window.dispatchEvent(new CustomEvent('ui:updateVitals',{detail:{hp:18,maxHp:18,mana:77,maxMana:81,stamina:77,maxStamina:77}}));window.dispatchEvent(new CustomEvent('ui:updateCombatHUD',{detail:{statuses:[{key:'satiated',turns:99,stacks:1}]}}));window.dispatchEvent(new CustomEvent('ui:updateQuestTracker',{detail:{focused:{title:'Scout the Quarter',progress:9,target:12}}}));window.ready=true;</script></body></html>`});
