  });
  await page.goto('http://jshack.test/');
  await page.waitForFunction(()=>window.ready,{},{timeout:10000}).catch(()=>{});
  const layout=await page.evaluate(()=>[...document.querySelectorAll('[data-resource]')].map(el=>({resource:el.dataset.resource,...Object.fromEntries(['x','y','width','height'].map(k=>[k,el.getBoundingClientRect()[k]])),parent:getComputedStyle(el.parentElement).display})));
  console.log(JSON.stringify({width,errors,layout}));
  await page.screenshot({path:`/tmp/jshack-hud-${width}.png`});
  if(errors.length || layout.length!==3 || layout.some(el=>Math.abs(el.y-layout[0].y)>1) || !(layout[0].x<layout[1].x&&layout[1].x<layout[2].x)) throw new Error('HUD columns failed');
  await page.close();
 }
}finally{await browser.close();}

